        Circuit("nurburg", "nurburgring", R.drawable.ic_circuit_de_1927, R.drawable.ic_circuit_de_1927_aod),
        Circuit("hockenheim", "hockenheimring", R.drawable.ic_circuit_de_1932, R.drawable.ic_circuit_de_1932_aod),
        Circuit("barcelona", "circuit de barcelona catalunya", R.drawable.ic_circuit_es_1991, R.drawable.ic_circuit_es_1991_aod),
        Circuit("madrid", "circuito de madring", R.drawable.ic_circuit_es_2026, R.drawable.ic_circuit_es_2026_aod),
