        Circuit("le castellet", "circuit paul ricard", R.drawable.ic_circuit_fr_1969, R.drawable.ic_circuit_fr_1969_aod),
        Circuit("silverstone", "silverstone circuit", R.drawable.ic_circuit_gb_1948, R.drawable.ic_circuit_gb_1948_aod),
        Circuit("budapest", "hungaroring", R.drawable.ic_circuit_hu_1986, R.drawable.ic_circuit_hu_1986_aod),
        Circuit("scarperia e san piero", "autodromo internazionale del mugello", R.drawable.ic_circuit_it_1914, R.drawable.ic_circuit_it_1914_aod),
        Circuit("monza", "autodromo nazionale monza", R.drawable.ic_circuit_it_1922, R.drawable.ic_circuit_it_1922_aod),
        Circuit("imola", "autodromo enzo e dino ferrari", R.drawable.ic_circuit_it_1953, R.drawable.ic_circuit_it_1953_aod),
