        Circuit("lusail", "losail international circuit", R.drawable.ic_circuit_qa_2004, R.drawable.ic_circuit_qa_2004_aod),
        Circuit("sochi", "sochi autodrom", R.drawable.ic_circuit_ru_2014, R.drawable.ic_circuit_ru_2014_aod),
